import json

def load_json(path):
    with open(path) as f:
        return json.load(f)

from collections import Counter

def word_freq(text):
    return dict(Counter(text.split()))

def dedup(xs):
    seen = set()
    return [x for x in xs if not (x in seen or seen.add(x))]

def my_max(xs):
    m = xs[0]
    for x in xs[1:]:
        if x > m:
            m = x
    return m

class Greeter:
    def __init__(self, name):
        self.name = name

    def greet(self):
        return f'Hello, {self.name}!'
